-- Mega artwork provider for Gen1Recomp: indexed by a TEMPORARY Mega form key,
-- never by a saved species slot. Does not install battle, Pokedex or party hooks.
--
-- The source atlas is generated by tools/build_mega_atlas.py and is independent
-- of g9-battle-sprites-gen3's owned Pokemon.frontPic/backPic/icon wrappers.
local Atlas = {}
local PIC_BOX = 64
local KINDS = {
  front = true, back = true, icon = true,
  front_shiny = true, back_shiny = true, icon_shiny = true,
}

-- Pure frame math: checks every offset before any texture is loaded.
function Atlas.locate(index, slug, kind, frame)
  if type(slug) ~= "string" or not KINDS[kind] then return nil end
  local forms = type(index) == "table" and index.forms
  local form = type(forms) == "table" and forms[slug]
  local cell = form and form.variants and form.variants[kind]
  local count = cell and tonumber(cell.frames)
  if not count or count < 1 then return nil end
  local n = math.floor(tonumber(frame) or 0) % count
  for _, seg in ipairs(cell.segments or {}) do
    local first, nseg, cols, fs = tonumber(seg.first), tonumber(seg.frames),
      tonumber(seg.cols), tonumber(seg.fs)
    if first and nseg and cols and cols > 0 and fs and fs > 0
        and n >= first and n < first + nseg then
      local localFrame = n - first
      return {
        file = string.format("battle_%s_%d.png", kind, seg.sheet),
        x = seg.ox + (localFrame % cols) * fs,
        y = seg.oy + math.floor(localFrame / cols) * fs,
        fs = fs, frame = n, frames = count,
        fps = tonumber(cell.fps) or 8, slug = slug, kind = kind,
      }
    end
  end
  return nil
end

-- A small bounded page cache matters: 156 full-resolution pages would consume
-- gigabytes if all loaded as GPU textures at once. Frames are separately cached.
function Atlas.new(mod, index, graphics, timer)
  if type(index) ~= "table" or index.schema ~= 1 or type(index.forms) ~= "table" then
    return nil, "unsupported or missing Mega atlas index"
  end
  local G = graphics
  local self = { index = index }
  local pageCache, pageOrder = {}, {}
  local frameCache, frameOrder = {}, {}
  local logged = {}

  local function warnOnce(key, message)
    if logged[key] then return end
    logged[key] = true
    if mod.log and type(mod.log.warn) == "function" then mod.log:warn("%s", message) end
  end

  local function touch(order, key)
    for i = 1, #order do
      if order[i] == key then table.remove(order, i); break end
    end
    order[#order + 1] = key
  end

  local function cache(cacheData, order, key, obj, max)
    cacheData[key] = obj
    touch(order, key)
    while #order > max do
      cacheData[table.remove(order, 1)] = nil
    end
  end

  local function imageFor(filename)
    if not (G and type(G.newImage) == "function") then return nil end
    local hit = pageCache[filename]
    if hit then touch(pageOrder, filename); return hit end
    local path = mod.path .. "/assets/runtime/atlas/" .. filename
    local ok, img = pcall(G.newImage, path)
    if not ok or not img then
      warnOnce(filename, "Mega atlas page unavailable: " .. filename .. " (" .. tostring(img) .. ")")
      return nil
    end
    if img.setFilter then img:setFilter("nearest", "nearest") end
    cache(pageCache, pageOrder, filename, img, 6)
    return img
  end

  local function indexFrame(slug, kind, frame)
    local cell = index.forms[slug] and index.forms[slug].variants
      and index.forms[slug].variants[kind]
    if not cell then return nil end
    local f = frame
    if f == nil then
      local t = type(timer) == "function" and timer() or 0
      f = math.floor((tonumber(t) or 0) * (tonumber(cell.fps) or 8))
    end
    return Atlas.locate(index, slug, kind, f)
  end

  function self.hasSprite(slug, kind)
    return Atlas.locate(index, slug, kind or "front", 0) ~= nil
  end

  function self.formInfo(slug)
    local form = index.forms[slug]
    if not form then return nil end
    -- Deliberately small copy; consumers cannot mutate our atlas coordinates.
    return { slug = slug, species = form.species, display_name = form.display_name,
             pbs_key = form.pbs_key, mega_stone = form.mega_stone,
             source_form = form.source_form }
  end

  function self.locate(slug, kind, frame)
    return indexFrame(slug, kind, frame)
  end

  -- Supply the full-resolution frame for a later HD-sprite integration. Its
  -- texture may outlive the six-page cache if held by another module.
  function self.frame(slug, kind, frame)
    local cell = indexFrame(slug, kind, frame)
    if not cell or not (G and type(G.newQuad) == "function") then return nil end
    local img = imageFor(cell.file)
    if not img then return nil end
    local w, h = img:getDimensions()
    if cell.x + cell.fs > w or cell.y + cell.fs > h then
      warnOnce(cell.file .. ":bounds", "Mega sprite cell outside atlas: " .. cell.file)
      return nil
    end
    local ok, quad = pcall(G.newQuad, cell.x, cell.y, cell.fs, cell.fs, w, h)
    if not ok then return nil end
    return { image = img, quad = quad, w = cell.fs, h = cell.fs,
             frame = cell.frame, frames = cell.frames, fps = cell.fps }
  end

  -- Engine-compatible {image, w=64, h=64}. This draws an individual frame into
  -- a 64x64 logical canvas; unlike a hook it does not modify any other sprites.
  -- Larger creatures are fitted and bottom-centred, provisionally; precise
  -- front/back battle anchoring and HD tagging belong to the G9 adapter later.
  function self.picture(slug, side, shiny, frame)
    if side ~= "front" and side ~= "back" and side ~= "icon" then return nil end
    local kind = side .. (shiny and "_shiny" or "")
    local location = indexFrame(slug, kind, frame)
    if not location then return nil end
    local key = slug .. "/" .. kind .. "/" .. location.frame
    local cached = frameCache[key]
    if cached then touch(frameOrder, key); return cached end
    if not (G and type(G.newCanvas) == "function" and type(G.draw) == "function"
        and type(G.setCanvas) == "function" and type(G.push) == "function"
        and type(G.pop) == "function") then return nil end
    local source = self.frame(slug, kind, location.frame)
    if not source then return nil end
    local ok, canvas = pcall(G.newCanvas, PIC_BOX, PIC_BOX, { dpiscale = 4 })
    if not ok or not canvas then
      warnOnce("canvas", "Mega art canvas is unavailable: " .. tostring(canvas))
      return nil
    end
    if canvas.setFilter then canvas:setFilter("nearest", "nearest") end
    local scale = math.min(1, PIC_BOX / source.w)
    local ox = (PIC_BOX - source.w * scale) / 2
    local oy = PIC_BOX - source.h * scale
    G.push("all")
    local drawn, err = pcall(function()
      if G.origin then G.origin() end
      if G.setScissor then G.setScissor() end
      if G.setShader then G.setShader() end
      if G.setBlendMode then G.setBlendMode("alpha") end
      if G.setColor then G.setColor(1, 1, 1, 1) end
      G.setCanvas(canvas)
      if G.clear then G.clear(0, 0, 0, 0) end
      G.draw(source.image, source.quad, ox, oy, 0, scale, scale)
    end)
    G.pop()
    if not drawn then
      warnOnce("draw", "Could not draw Mega sprite: " .. tostring(err))
      return nil
    end
    local entry = { image = canvas, w = PIC_BOX, h = PIC_BOX }
    cache(frameCache, frameOrder, key, entry, 48)
    return entry
  end

  function self.stats()
    return { forms = (function() local n = 0; for _ in pairs(index.forms) do n = n + 1 end; return n end)(),
             cachedPages = #pageOrder, cachedFrames = #frameOrder }
  end
  return self
end

return Atlas
